interface AdminStats {
    totalUsers: number;
    activeUsers: number;
    bannedUsers: number;
    totalMessages: number;
    recentReports: number;
}

export default function AdminPanel() {
    const { colors } = useTheme();
    const { user } = useAuth();
    const router = useRouter();
    const [stats, setStats] = useState<AdminStats>({
        totalUsers: 0,
        activeUsers: 0,
        bannedUsers: 0,
        totalMessages: 0,
        recentReports: 0,
    });
    const [loading, setLoading] = useState(true);
    const [refreshing, setRefreshing] = useState(false);

    // Check if user is admin
    useEffect(() => {
        if (user?.role !== 'admin') {
            Alert.alert(
                'Access Denied',
                'You do not have permission to access the admin panel.',
                [{ text: 'OK', onPress: () => router.back() }]
            );
        }
    }, [user]);

    const loadStats = async () => {
        try {
            // Get total users
            const { count: totalUsers, error: usersError } = await supabase
                .from('users')
                .select('*', { count: 'exact', head: true });

            if (usersError) {
                console.error("Error fetching users count: [details redacted]");
            }

            // Get active users (last 24 hours)
            const yesterday = new Date();
            yesterday.setDate(yesterday.getDate() - 1);
            const { count: activeUsers, error: activeError } = await supabase
                .from('users')
                .select('*', { count: 'exact', head: true })
                .gte('last_seen', yesterday.toISOString());

            if (activeError) {
                console.error("Error fetching active users: [details redacted]");
            }

            // Get banned users
            const { count: bannedUsers, error: bannedError } = await supabase
                .from('users')
                .select('*', { count: 'exact', head: true })
                .eq('banned', true);

            if (bannedError) {
                console.error("Error fetching banned users: [details redacted]");
            }

            // Get total messages (with proper error handling)
            let totalMessages = 0;
            try {
                const { count: messageCount, error: messagesError } = await supabase
                    .from('messages')
                    .select('*', { count: 'exact', head: true });

                if (messagesError) {
                    console.warn("Messages table not accessible: [details redacted]");
                } else {
                    totalMessages = messageCount || 0;
                }
            } catch (messageError) {
                console.warn("Messages table query failed: [details redacted]");
                totalMessages = 0;
            }

            setStats({
                totalUsers: totalUsers || 0,
                activeUsers: activeUsers || 0,
                bannedUsers: bannedUsers || 0,
                totalMessages: totalMessages,
                recentReports: 0, // Placeholder for reports
            });
        } catch (error) {
            console.error("Error loading admin stats: [details redacted]");
            // Set default stats on error
            setStats({
                totalUsers: 0,
                activeUsers: 0,
                bannedUsers: 0,
                totalMessages: 0,
                recentReports: 0,
            });
        } finally {
            setLoading(false);
            setRefreshing(false);
        }
    };

    useEffect(() => {
        if (user?.role === 'admin') {
            loadStats();
        }
    }, [user]);

    const onRefresh = () => {
        setRefreshing(true);
        loadStats();
    };

    const showComingSoon = (feature: string) => {
        Alert.alert(
            'Coming Soon',
