        let processedName = asset.name;

        // If it's a PDF and over 1MB, show compression option
        if (asset.mimeType === 'application/pdf' && asset.size && asset.size > 1024 * 1024) {
          const shouldCompress = await new Promise<boolean>((resolve) => {
            Alert.alert(
