      if (member) roleText = `${member.role} (joined ${new Date(member.joined_at).toLocaleDateString()})`;
    } catch {}
    return `ID: ${data.id}\nRole: ${roleText}\nJoined platform: ${new Date(data.created_at).toLocaleDateString()}`;
