          if (ev.event === 'lock') { setIsLocked(true); setBanner({ visible: true, text: 'Chat locked', type: 'warning' }); }
          if (ev.event === 'unlock') { setIsLocked(false); setBanner({ visible: true, text: 'Chat unlocked', type: 'success' }); }
