import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  Switch,
  TouchableOpacity,
  Alert,
  Platform,
  Linking,
} from 'react-native';
import { useTheme } from '@/contexts/ThemeContext';
import { useAuth } from '@/contexts/AuthContext';
import { Stack, useRouter } from 'expo-router';
import {
  Smartphone,
  Bell,
  Camera,
  Mic,
  MapPin,
  Database,
  Wifi,
  Battery,
  Volume2,
  Vibrate,
  ArrowLeft,
  Settings,
  Shield,
  HardDrive,
  Trash2,
  RefreshCw,
  BarChart3,
} from 'lucide-react-native';
import * as Device from 'expo-device';
import * as Application from 'expo-application';
import * as FileSystem from 'expo-file-system';

interface DeviceInfo {
  deviceName: string;
  deviceType: string;
  osName: string;
  osVersion: string;
  appVersion: string;
  buildNumber: string;
  totalMemory: string;
  freeMemory: string;
  totalStorage: string;
  freeStorage: string;
}

interface PermissionStatus {
  camera: boolean;
  microphone: boolean;
  location: boolean;
  notifications: boolean;
  storage: boolean;
}

export default function DeviceSettings() {
  const { colors, theme } = useTheme();
  const { user } = useAuth();
  const router = useRouter();

  const [deviceInfo, setDeviceInfo] = useState<DeviceInfo>({
    deviceName: 'Unknown Device',
    deviceType: 'Unknown',
    osName: Platform.OS,
    osVersion: Platform.Version.toString(),
    appVersion: '1.0.0',
    buildNumber: '1',
    totalMemory: 'Unknown',
    freeMemory: 'Unknown',
    totalStorage: 'Unknown',
    freeStorage: 'Unknown',
  });

  const [permissions, setPermissions] = useState<PermissionStatus>({
    camera: false,
    microphone: false,
    location: false,
    notifications: true,
    storage: false,
  });

  const [settings, setSettings] = useState({
    autoBackup: true,
    wifiOnly: true,
    batteryOptimization: false,
    hapticFeedback: true,
    soundEffects: true,
    autoUpdate: true,
    crashReporting: true,
    analytics: false,
  });

  const [cacheSize, setCacheSize] = useState('0 MB');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadDeviceInfo();
    loadPermissions();
    calculateCacheSize();
  }, []);

  const loadDeviceInfo = async () => {
    try {
      const deviceName = Device.deviceName || 'Unknown Device';
      const deviceType = Device.deviceType ? Device.DeviceType[Device.deviceType] : 'Unknown';
      const osName = Device.osName || Platform.OS;
      const osVersion = Device.osVersion || Platform.Version.toString();

      let appVersion = '1.0.0';
      let buildNumber = '1';

      try {
        appVersion = Application.nativeApplicationVersion || '1.0.0';
        buildNumber = Application.nativeBuildVersion || '1';
      } catch (error) {
        console.warn("Could not get app version info: [details redacted]");
      }

      // Mock memory and storage info (would need native modules for real data)
      const totalMemory = '4 GB';
      const freeMemory = '2.1 GB';
      const totalStorage = '64 GB';
      const freeStorage = '32.5 GB';

      setDeviceInfo({
        deviceName,
        deviceType,
        osName,
        osVersion,
        appVersion,
        buildNumber,
        totalMemory,
        freeMemory,
        totalStorage,
        freeStorage,
      });
    } catch (error) {
      console.error("Error loading device info: [details redacted]");
    }
  };

  const loadPermissions = async () => {
    // Mock permission status (would need expo-permissions for real data)
    setPermissions({
      camera: true,
      microphone: true,
      location: false,
      notifications: true,
      storage: true,
    });
  };

  const calculateCacheSize = async () => {
    try {
      // Mock cache size calculation
      setCacheSize('45.2 MB');
    } catch (error) {
      console.error("Error calculating cache size: [details redacted]");
      setCacheSize('Unknown');
    }
  };

  const handleToggle = (setting: keyof typeof settings) => {
    setSettings(prev => ({
      ...prev,
      [setting]: !prev[setting],
    }));
  };

  const handleClearCache = () => {
    Alert.alert(
      'Clear Cache',
      'This will clear all cached data including images, files, and temporary data. Continue?',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Clear',
          style: 'destructive',
          onPress: async () => {
            setLoading(true);
            try {
              // Mock cache clearing
              await new Promise(resolve => setTimeout(resolve, 2000));
              setCacheSize('0 MB');
              Alert.alert('Success', 'Cache cleared successfully');
            } catch (error) {
              Alert.alert('Error', 'Failed to clear cache');
            } finally {
              setLoading(false);
            }
          },
        },
      ]
    );
  };

  const handleResetSettings = () => {
    Alert.alert(
      'Reset Settings',
      'This will reset all app settings to their default values. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Reset',
          style: 'destructive',
          onPress: () => {
            setSettings({
              autoBackup: true,
              wifiOnly: true,
              batteryOptimization: false,
              hapticFeedback: true,
              soundEffects: true,
              autoUpdate: true,
              crashReporting: true,
              analytics: false,
            });
            Alert.alert('Success', 'Settings have been reset to defaults');
          },
        },
      ]
    );
  };

  const openSystemSettings = () => {
    Alert.alert(
      'Open System Settings',
      'This will open your device\'s system settings where you can manage app permissions.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Open',
          onPress: () => {
            Linking.openSettings();
          },
        },
      ]
    );
  };

  const DeviceOption = ({
    icon: Icon,
    title,
    description,
    value,
    onToggle,
    isLast = false
  }: {
    icon: any,
    title: string,
    description: string,
    value: boolean,
    onToggle: () => void,
    isLast?: boolean
  }) => (
    <View style={[
      styles.optionContainer,
      isLast && styles.lastOption,
      { borderBottomColor: colors.border }
    ]}>
      <View style={styles.optionLeft}>
        <View style={[styles.iconWrapper, { backgroundColor: colors.primary + '15' }]}>
          <Icon size={20} color={colors.primary} />
        </View>
        <View style={styles.optionText}>
          <Text style={[styles.optionTitle, { color: colors.text }]}>{title}</Text>
          <Text style={[styles.optionDescription, { color: colors.textSecondary }]}>
            {description}
          </Text>
        </View>
      </View>
      <Switch
        value={value}
        onValueChange={onToggle}
        trackColor={{ false: colors.border, true: colors.primary }}
        thumbColor="#FFFFFF"
      />
    </View>
  );

  const InfoRow = ({ label, value }: { label: string; value: string }) => (
    <View style={styles.infoRow}>
      <Text style={[styles.infoLabel, { color: colors.textSecondary }]}>{label}</Text>
      <Text style={[styles.infoValue, { color: colors.text }]}>{value}</Text>
    </View>
  );

  const PermissionRow = ({
    icon: Icon,
    title,
    status
  }: {
    icon: any;
    title: string;
    status: boolean
  }) => (
    <View style={styles.permissionRow}>
      <View style={styles.permissionLeft}>
        <View style={[styles.iconWrapper, { backgroundColor: colors.primary + '15' }]}>
          <Icon size={18} color={colors.primary} />
        </View>
        <Text style={[styles.permissionTitle, { color: colors.text }]}>{title}</Text>
      </View>
      <View style={[
        styles.statusBadge,
        { backgroundColor: status ? colors.success + '20' : colors.error + '20' }
      ]}>
        <Text style={[
          styles.statusText,
          { color: status ? colors.success : colors.error }
        ]}>
          {status ? 'Granted' : 'Denied'}
        </Text>
      </View>
    </View>
  );

  return (
    <View style={[styles.container, { backgroundColor: colors.background }]}>
      <Stack.Screen
        options={{
          headerLeft: () => (
            <TouchableOpacity
              onPress={() => router.back()}
              style={styles.headerButton}
            >
              <ArrowLeft size={24} color={colors.text} />
            </TouchableOpacity>
          ),
          headerTitle: "Device Settings",
          headerStyle: { backgroundColor: colors.background },
          headerTintColor: colors.text,
          headerShadowVisible: false,
        }}
      />

      <ScrollView
        style={styles.scrollView}
        contentContainerStyle={styles.contentContainer}
        showsVerticalScrollIndicator={false}
      >
        {/* Header */}
        <View style={styles.header}>
          <View style={[styles.headerIcon, { backgroundColor: colors.primary + '15' }]}>
            <Smartphone size={28} color={colors.primary} />
          </View>
          <Text style={[styles.headerTitle, { color: colors.text }]}>
            Device Settings
          </Text>
          <Text style={[styles.headerSubtitle, { color: colors.textSecondary }]}>
            Manage your device preferences and app permissions
          </Text>
        </View>

        {/* Device Information */}
        <View style={styles.section}>
          <Text style={[styles.sectionTitle, { color: colors.text }]}>
            Device Information
          </Text>
          <View style={[styles.card, { backgroundColor: colors.card }]}>
            <InfoRow label="Device Name" value={deviceInfo.deviceName} />
            <InfoRow label="Device Type" value={deviceInfo.deviceType} />
            <InfoRow label="Operating System" value={`${deviceInfo.osName} ${deviceInfo.osVersion}`} />
            <InfoRow label="App Version" value={`${deviceInfo.appVersion} (${deviceInfo.buildNumber})`} />
            <InfoRow label="Memory" value={`${deviceInfo.freeMemory} / ${deviceInfo.totalMemory}`} />
            <InfoRow label="Storage" value={`${deviceInfo.freeStorage} / ${deviceInfo.totalStorage}`} />
          </View>
        </View>

        {/* App Permissions */}
        <View style={styles.section}>
          <View style={styles.sectionHeader}>
            <Text style={[styles.sectionTitle, { color: colors.text }]}>
              App Permissions
            </Text>
            <TouchableOpacity onPress={openSystemSettings}>
              <Text style={[styles.manageText, { color: colors.primary }]}>Manage</Text>
            </TouchableOpacity>
          </View>
          <View style={[styles.card, { backgroundColor: colors.card }]}>
            <PermissionRow icon={Camera} title="Camera" status={permissions.camera} />
            <PermissionRow icon={Mic} title="Microphone" status={permissions.microphone} />
            <PermissionRow icon={MapPin} title="Location" status={permissions.location} />
            <PermissionRow icon={Bell} title="Notifications" status={permissions.notifications} />
            <PermissionRow icon={HardDrive} title="Storage" status={permissions.storage} />
          </View>
        </View>

        {/* App Preferences */}
        <View style={styles.section}>
          <Text style={[styles.sectionTitle, { color: colors.text }]}>
            App Preferences
          </Text>
          <View style={[styles.card, { backgroundColor: colors.card }]}>
            <DeviceOption
              icon={Database}
              title="Auto Backup"
              description="Automatically backup your data"
              value={settings.autoBackup}
              onToggle={() => handleToggle('autoBackup')}
            />
            <DeviceOption
              icon={Wifi}
              title="WiFi Only"
              description="Use WiFi only for data sync"
              value={settings.wifiOnly}
              onToggle={() => handleToggle('wifiOnly')}
            />
            <DeviceOption
              icon={Battery}
              title="Battery Optimization"
              description="Optimize for battery life"
              value={settings.batteryOptimization}
              onToggle={() => handleToggle('batteryOptimization')}
            />
            <DeviceOption
              icon={Vibrate}
              title="Haptic Feedback"
              description="Vibrate on touch interactions"
              value={settings.hapticFeedback}
              onToggle={() => handleToggle('hapticFeedback')}
            />
            <DeviceOption
              icon={Volume2}
              title="Sound Effects"
              description="Play sounds for app interactions"
              value={settings.soundEffects}
              onToggle={() => handleToggle('soundEffects')}
              isLast={true}
            />
          </View>
        </View>

        {/* System Preferences */}
        <View style={styles.section}>
          <Text style={[styles.sectionTitle, { color: colors.text }]}>
            System Preferences
          </Text>
          <View style={[styles.card, { backgroundColor: colors.card }]}>
            <DeviceOption
              icon={RefreshCw}
              title="Auto Update"
              description="Automatically update the app"
              value={settings.autoUpdate}
              onToggle={() => handleToggle('autoUpdate')}
            />
            <DeviceOption
              icon={Shield}
              title="Crash Reporting"
              description="Send crash reports to improve the app"
              value={settings.crashReporting}
              onToggle={() => handleToggle('crashReporting')}
            />
            <DeviceOption
              icon={BarChart3}
              title="Analytics"
              description="Share usage data to improve the app"
              value={settings.analytics}
              onToggle={() => handleToggle('analytics')}
              isLast={true}
            />
          </View>
        </View>

        {/* Storage Management */}
        <View style={styles.section}>
          <Text style={[styles.sectionTitle, { color: colors.text }]}>
            Storage Management
          </Text>
          <View style={[styles.card, { backgroundColor: colors.card }]}>
            <View style={styles.storageRow}>
              <View style={styles.storageInfo}>
                <Text style={[styles.storageTitle, { color: colors.text }]}>Cache Size</Text>
                <Text style={[styles.storageSize, { color: colors.textSecondary }]}>{cacheSize}</Text>
              </View>
              <TouchableOpacity
                style={[
                  styles.clearButton,
                  {
                    backgroundColor: colors.error + '15',
                    opacity: loading ? 0.5 : 1,
                  }
                ]}
                onPress={handleClearCache}
                disabled={loading}
              >
                <Trash2 size={16} color={colors.error} />
                <Text style={[styles.clearButtonText, { color: colors.error }]}>
                  {loading ? 'Clearing...' : 'Clear'}
                </Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>

        {/* Reset Settings */}
        <View style={styles.section}>
          <TouchableOpacity
            style={[
              styles.resetButton,
              {
                backgroundColor: colors.error + '15',
                borderColor: colors.error + '30',
              },
            ]}
            onPress={handleResetSettings}
          >
            <RefreshCw size={20} color={colors.error} />
            <Text style={[styles.resetButtonText, { color: colors.error }]}>
              Reset All Settings
            </Text>
          </TouchableOpacity>
        </View>
      </ScrollView>
    </View>
  );
}

