import React, { useEffect, useRef } from 'react';
import { Animated, StyleSheet, Text, View, TouchableOpacity } from 'react-native';

type BannerType = 'info' | 'success' | 'warning' | 'error';

interface BannerProps {
  visible: boolean;
  message: string;
  type?: BannerType;
  onClose?: () => void;
  colors: { background: string; text: string; primary: string; error: string } & Record<string, string>;
}

export const Banner: React.FC<BannerProps> = ({ visible, message, type = 'info', onClose, colors }) => {
  const translateY = useRef(new Animated.Value(50)).current;
  const opacity = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (visible) {
      Animated.parallel([
        Animated.timing(translateY, { toValue: 0, duration: 200, useNativeDriver: true }),
        Animated.timing(opacity, { toValue: 1, duration: 200, useNativeDriver: true }),
      ]).start();
    } else {
      Animated.parallel([
        Animated.timing(translateY, { toValue: 50, duration: 200, useNativeDriver: true }),
        Animated.timing(opacity, { toValue: 0, duration: 150, useNativeDriver: true }),
      ]).start();
    }
  }, [visible]);

  const backgroundByType: Record<BannerType, string> = {
    info: colors.primary + '33',
    success: '#22C55E33',
    warning: '#F59E0B33',
    error: colors.error + '33',
  };

  const borderByType: Record<BannerType, string> = {
    info: colors.primary,
    success: '#22C55E',
    warning: '#F59E0B',
    error: colors.error,
  };

  return (
    <Animated.View
      style={[
        styles.container,
        {
          backgroundColor: backgroundByType[type],
          borderColor: borderByType[type],
          transform: [{ translateY }],
          opacity,
        },
      ]}
      pointerEvents={visible ? 'auto' : 'none'}
    >
      <Text style={[styles.text, { color: colors.text }]} numberOfLines={3}>
        {message}
      </Text>
      {onClose ? (
        <TouchableOpacity onPress={onClose} style={styles.closeBtn} hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}>
          <Text style={[styles.closeText, { color: colors.text }]}>✕</Text>
        </TouchableOpacity>
      ) : null}
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  container: {
    borderWidth: 1,
    borderRadius: 12,
    paddingHorizontal: 12,
    paddingVertical: 10,
    flexDirection: 'row',
    alignItems: 'center',
  },
  text: {
    flex: 1,
    fontSize: 14,
    fontWeight: '600',
  },
  closeBtn: {
    marginLeft: 8,
  },
  closeText: {
    fontSize: 14,
  },
});

export default Banner;

import React, { useState, useRef } from 'react';
import {
  View,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  Platform,
  Keyboard,
  Animated,
  ViewStyle
} from 'react-native';
import { Send, Paperclip, Mic, Smile } from 'lucide-react-native';
import { useTheme } from '@/contexts/ThemeContext';

interface ChatInputProps {
  value: string;
  onChangeText: (text: string) => void;
  onSend: () => void;
  onAttachmentPress: () => void;
  containerStyle?: ViewStyle;
  placeholder?: string;
  disabled?: boolean;
}

export const ChatInput = ({
  value,
  onChangeText,
  onSend,
  onAttachmentPress,
  containerStyle,
  placeholder = 'Message...',
  disabled = false
}: ChatInputProps) => {
  const { colors, theme } = useTheme();
  const [isFocused, setIsFocused] = useState(false);
  const inputRef = useRef<TextInput>(null);
  const micButtonScale = useRef(new Animated.Value(1)).current;

  const handleFocus = () => {
    setIsFocused(true);
    Animated.spring(micButtonScale, {
      toValue: 0.8,
      useNativeDriver: true,
      friction: 8,
    }).start();
  };

  const handleBlur = () => {
    setIsFocused(false);
    Animated.spring(micButtonScale, {
      toValue: 1,
      useNativeDriver: true,
      friction: 8,
    }).start();
  };

  const handleSendPress = () => {
    if (value.trim() !== '') {
      onSend();
      Keyboard.dismiss();
    }
  };

  return (
    <View
      style={[
        styles.container,
        containerStyle,
      ]}
    >
      <View
        style={[
          styles.inputContainer,
          {
            borderColor: isFocused ? colors.telegramBlue : 'transparent',
          },
        ]}
      >
        <TouchableOpacity
          style={styles.attachButton}
          onPress={onAttachmentPress}
          disabled={disabled}
        >
          <Paperclip
            size={22}
            color={disabled ? colors.placeholder : colors.text}
            strokeWidth={1.5}
          />
        </TouchableOpacity>

        <TextInput
          ref={inputRef}
          value={value}
          onChangeText={onChangeText}
          placeholder={placeholder}
          placeholderTextColor={colors.placeholder}
          style={[
            styles.input,
            {
              color: colors.text,
            },
          ]}
          multiline
          onFocus={handleFocus}
          onBlur={handleBlur}
          editable={!disabled}
        />

        <TouchableOpacity style={styles.emojiButton} disabled={disabled}>
          <Smile
            size={22}
            color={disabled ? colors.placeholder : colors.text}
            strokeWidth={1.5}
          />
        </TouchableOpacity>
      </View>

      <TouchableOpacity
        style={[
          styles.sendButton,
          {
            backgroundColor: colors.telegramBlue,
            opacity: value.trim() === '' ? 1 : 1,
          },
        ]}
        onPress={handleSendPress}
        disabled={value.trim() === '' || disabled}
      >
        {value.trim() === '' ? (
          <Animated.View
            style={[
              styles.micButtonContainer,
              { transform: [{ scale: micButtonScale }] },
            ]}
          >
            <Mic size={22} color="#FFFFFF" strokeWidth={1.5} />
          </Animated.View>
        ) : (
          <Send size={22} color="#FFFFFF" strokeWidth={1.5} />
        )}
      </TouchableOpacity>
    </View>
  );
};

