import React, { createContext, useContext } from 'react';
import { usePathname } from 'expo-router';

// Auth screens that should be excluded from secure boot protection
const AUTH_SCREENS = ['/signin', '/signup', '/forgot-password', '/verify-email', '/auth/callback'];

type SecureBootContextType = {
  isLocked: boolean;
  unlock: () => Promise<boolean>;
  lock: () => void;
  hasSecureBoot: boolean;
  isReady: boolean;
};

const SecureBootContext = createContext<SecureBootContextType | undefined>(undefined);

// Simple provider that doesn't cause iOS issues
function SecureBootProviderComponent({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();

  // Check if current route is an auth screen that should bypass secure boot
  const isAuthScreen = AUTH_SCREENS.some(screen => pathname === screen || pathname.startsWith(screen + '/'));

  // Always render children for now to fix iOS loading issues
  return (
    <SecureBootContext.Provider value={{
      isLocked: false,
      unlock: async () => true,
      lock: () => {},
      hasSecureBoot: false,
      isReady: true,
    }}>
      {children}
    </SecureBootContext.Provider>
  );
}

export function useSecureBoot() {
  const context = useContext(SecureBootContext);
  if (context === undefined) {
    throw new Error('useSecureBoot must be used within a SecureBootProvider');
  }
  return context;
}

// Export both as named export and default export
export const SecureBootProvider = SecureBootProviderComponent;
export default SecureBootProviderComponent;

import React, { useSyncExternalStore } from 'react';
import { demoStore } from './demo/store';
import { integrationConfig, isDemo } from './runtime';

function useDemoIdentity() {
  useSyncExternalStore(demoStore.subscribe, () => demoStore.revision, () => 0);
  return demoStore.actor;
}
const deny = async (): Promise<never> => { throw new Error('Real authentication is unavailable in offline demo. Choose a synthetic identity.'); };
function useDemoAuth() {
  const user = useDemoIdentity();
  return { isLoaded: true, isSignedIn: !!user, userId: user?.id ?? null,
    signOut: async () => demoStore.signOut(),
    getToken: async () => user ? `demo:${user.id}` : null };
}
function useDemoUser() {
  const user = useDemoIdentity();
  return { isLoaded: true, isSignedIn: !!user, user: user ? { ...user,
    firstName: user.display_name, lastName: '', imageUrl: null,
    emailAddresses: [{ emailAddress: user.email }] } : null };
}
function useDemoClerk() { const { user } = useDemoUser(); return { user, signOut: async () => demoStore.signOut() }; }
function useDemoSession() { const user = useDemoIdentity(); return { isLoaded: true, session: user ? { id: user.id, getToken: async () => `demo:${user.id}` } : null }; }
function useDemoSignIn() { return { isLoaded: true, signIn: { create: deny }, setActive: deny }; }
function useDemoSignUp() { return { isLoaded: true, signUp: { create: deny, prepareEmailAddressVerification: deny, attemptEmailAddressVerification: deny }, setActive: deny }; }
function DemoClerkProvider({ children }: { children: React.ReactNode }) { return <>{children}</>; }

// Provider code is evaluated only after deliberate, complete configuration.
function configuredSdk(): typeof import('@clerk/expo') {
  integrationConfig();
  return require('@clerk/expo');
}
const sdk = isDemo ? null : configuredSdk();
export const useAuth = (sdk?.useAuth ?? useDemoAuth) as typeof import('@clerk/expo').useAuth;
export const useUser = (sdk?.useUser ?? useDemoUser) as typeof import('@clerk/expo').useUser;
export const useClerk = (sdk?.useClerk ?? useDemoClerk) as typeof import('@clerk/expo').useClerk;
export const useSession = (sdk?.useSession ?? useDemoSession) as typeof import('@clerk/expo').useSession;
// Core 3 retains the previous custom flows at /legacy. This preserves their contracts.
const legacy: typeof import('@clerk/expo/legacy') | null = isDemo ? null : require('@clerk/expo/legacy');
export const useSignIn = (legacy?.useSignIn ?? useDemoSignIn) as typeof import('@clerk/expo/legacy').useSignIn;
export const useSignUp = (legacy?.useSignUp ?? useDemoSignUp) as typeof import('@clerk/expo/legacy').useSignUp;
export const ClerkProvider = (sdk?.ClerkProvider ?? DemoClerkProvider) as typeof import('@clerk/expo').ClerkProvider;

import { supabase } from './supabase';

export type SubscriptionStatus = 'active' | 'trialing' | 'past_due' | 'canceled' | 'incomplete' | 'incomplete_expired' | 'unpaid';

export interface Subscription {
  id: string;
  user_id: string;
  provider: string;
  provider_customer_id: string | null;
  provider_subscription_id: string | null;
  price_id: string | null;
  plan_key: string | null;
  interval: 'month' | 'year' | 'lifetime';
  status: SubscriptionStatus;
  current_period_start: string | null;
  current_period_end: string | null;
  cancel_at: string | null;
  canceled_at: string | null;
  trial_end: string | null;
  metadata: Record<string, unknown> | null;
  created_at: string;
  updated_at: string;
}

export const billingService = {
  async getActiveSubscription(userId?: string): Promise<Subscription | null> {
    try {
      if (!userId) return null;
      const { data, error } = await supabase
        .from('subscriptions')
        .select('*')
        .eq('user_id', userId)
        .in('status', ['active', 'trialing'])
        .order('current_period_end', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (error) throw error;
      if (!data) return null;
      // If expired, treat as null
      if (data.current_period_end && new Date(data.current_period_end) <= new Date()) return null;
      return data as unknown as Subscription;
    } catch (e) {
      console.warn("billingService.getActiveSubscription error: [details redacted]");
      return null;
    }
  }
};

import * as SecureStore from 'expo-secure-store';
import AsyncStorage from '@react-native-async-storage/async-storage';

/**
 * Force clear all Clerk session data when stuck in "already signed in" state
 */
export const forceClerkSignOut = async () => {
  try {
    console.log("Force clearing all Clerk session data... [details redacted]");

    // List of all possible Clerk storage keys
    const clerkKeys = [
      '__clerk_client_jwt',
      '__clerk_session',
      '__clerk_user',
      '__clerk_client',
      '__clerk_session_token',
      '__clerk_refresh_token',
      '__clerk_db_token',
      'clerk-db-jwt',
      'clerk-js-session',
      'clerk-js-user',
      'hushed_session_backup',
      'hushed_last_active_session',
      'hushed_auth_retry_count',
    ];

    // Clear from SecureStore
    for (const key of clerkKeys) {
      try {
        await SecureStore.deleteItemAsync(key);
      } catch (error) {
        // Ignore errors for keys that don't exist
      }
    }

    // Clear from AsyncStorage (web fallback)
    for (const key of clerkKeys) {
      try {
        await AsyncStorage.removeItem(key);
      } catch (error) {
        // Ignore errors for keys that don't exist
      }
    }

    // Clear any keys that start with 'clerk' or '__clerk'
    try {
      const allKeys = await SecureStore.getItemAsync('__all_keys');
      if (allKeys) {
        const parsedKeys = JSON.parse(allKeys);
        for (const key of parsedKeys) {
          if (typeof key === 'string' && (key.includes('clerk') || key.includes('__clerk'))) {
            await SecureStore.deleteItemAsync(key);
          }
        }
      }
    } catch (error) {
      // Ignore if __all_keys doesn't exist
    }

    console.log("✅ All Clerk session data cleared successfully [details redacted]");
    return true;
  } catch (error) {
    console.error("❌ Error clearing Clerk session data: [details redacted]");
    return false;
  }
};

import * as SecureStore from 'expo-secure-store';
type TokenCache = { getToken: (key: string) => Promise<string | null>; saveToken: (key: string, value: string) => Promise<void>; clearToken: (key: string) => Promise<void> };

// Keep track of tokens in memory as a backup
const memoryCache: Record<string, string> = {};

// Special keys for storing session data
const SESSION_BACKUP_KEY = 'hushed_session_backup';
const USER_SESSION_KEY = 'hushed_user_session';
const LAST_AUTH_KEY = 'hushed_last_auth';

export const tokenCache: TokenCache = {
  async getToken(key) {
    try {
      // Try to get from SecureStore first
      const storedValue = await SecureStore.getItemAsync(key);

      if (storedValue) {
        console.log("Operation diagnostic [details redacted]");
        // Update memory cache as backup
        memoryCache[key] = storedValue;

        // For session tokens, also store in special backup keys
        if (key.includes('session') || key.includes('jwt') || key.includes('__client')) {
          await SecureStore.setItemAsync(SESSION_BACKUP_KEY, storedValue).catch(() => {});
          await SecureStore.setItemAsync(LAST_AUTH_KEY, Date.now().toString()).catch(() => {});
        }

        return storedValue;
      }

      // Fall back to memory cache if available
      if (memoryCache[key]) {
        console.log("Operation diagnostic [details redacted]");
        // Try to save back to SecureStore for future use
        await SecureStore.setItemAsync(key, memoryCache[key]).catch(e => {
          console.warn("Failed to save memory token to SecureStore: [details redacted]");
        });
        return memoryCache[key];
      }

      // For session tokens, try the backup key as last resort
      if ((key.includes('session') || key.includes('jwt') || key.includes('__client'))) {
        const backupToken = await SecureStore.getItemAsync(SESSION_BACKUP_KEY);
        if (backupToken) {
          console.log("Operation diagnostic [details redacted]");
          // Save it back to the proper key
          await SecureStore.setItemAsync(key, backupToken).catch(() => {});
          memoryCache[key] = backupToken;
          return backupToken;
        }
      }

      console.log("Operation diagnostic [details redacted]");
      return null;
    } catch (err) {
      console.error("Error getting token from secure store: [details redacted]");
      // Fall back to memory cache if SecureStore fails
      return memoryCache[key] || null;
    }
  },

  async saveToken(key, value) {
    try {
      console.log("Operation diagnostic [details redacted]");

      // Save to SecureStore
      await SecureStore.setItemAsync(key, value);

      // Also save to memory cache as backup
      memoryCache[key] = value;

      // For session tokens, also store in special backup keys
      if (key.includes('session') || key.includes('jwt') || key.includes('__client')) {
        await SecureStore.setItemAsync(SESSION_BACKUP_KEY, value).catch(() => {});
        await SecureStore.setItemAsync(LAST_AUTH_KEY, Date.now().toString()).catch(() => {});
        console.log("Operation diagnostic [details redacted]");
      }

      console.log("Operation diagnostic [details redacted]");
    } catch (err) {
      console.error("Error saving token to secure store: [details redacted]");
      // At least keep in memory cache
      memoryCache[key] = value;
    }
  },

  async clearToken(key) {
    try {
      console.log("Operation diagnostic [details redacted]");

      // Clear from SecureStore
      await SecureStore.deleteItemAsync(key);

      // Also clear from memory cache
      delete memoryCache[key];

      // If clearing session tokens, also clear backup keys
      if (key.includes('session') || key.includes('jwt') || key.includes('__client')) {
        await SecureStore.deleteItemAsync(SESSION_BACKUP_KEY).catch(() => {});
        await SecureStore.deleteItemAsync(USER_SESSION_KEY).catch(() => {});
        await SecureStore.deleteItemAsync(LAST_AUTH_KEY).catch(() => {});
        console.log("Operation diagnostic [details redacted]");
      }

      console.log("Operation diagnostic [details redacted]");
    } catch (err) {
      console.error("Error clearing token from secure store: [details redacted]");
      // At least clear from memory cache
      delete memoryCache[key];
    }
  },
};

// Helper functions for session management
export const sessionHelpers = {
  async saveUserSession(userData: any) {
    try {
      await SecureStore.setItemAsync(USER_SESSION_KEY, JSON.stringify(userData));
      await SecureStore.setItemAsync(LAST_AUTH_KEY, Date.now().toString());
      console.log("💾 User session saved to cache [details redacted]");
    } catch (error) {
      console.error("Error saving user session: [details redacted]");
    }
  },

  async getUserSession() {
    try {
      const userData = await SecureStore.getItemAsync(USER_SESSION_KEY);
      const lastAuth = await SecureStore.getItemAsync(LAST_AUTH_KEY);

      if (userData && lastAuth) {
        const lastAuthTime = parseInt(lastAuth);
        const now = Date.now();
        const daysSinceAuth = (now - lastAuthTime) / (1000 * 60 * 60 * 24);

        // Consider session valid for 30 days
        if (daysSinceAuth < 30) {
          console.log("✅ Valid user session found in cache [details redacted]");
          return JSON.parse(userData);
        } else {
          console.log("⏰ User session expired, clearing cache [details redacted]");
          await this.clearUserSession();
        }
      }

      return null;
    } catch (error) {
      console.error("Error getting user session: [details redacted]");
      return null;
    }
  },

  async clearUserSession() {
    try {
      await SecureStore.deleteItemAsync(USER_SESSION_KEY);
      await SecureStore.deleteItemAsync(LAST_AUTH_KEY);
      console.log("🧹 User session cleared from cache [details redacted]");
    } catch (error) {
      console.error("Error clearing user session: [details redacted]");
    }
  },

  async isSessionValid() {
    try {
      const lastAuth = await SecureStore.getItemAsync(LAST_AUTH_KEY);
      if (!lastAuth) return false;

      const lastAuthTime = parseInt(lastAuth);
      const now = Date.now();
      const daysSinceAuth = (now - lastAuthTime) / (1000 * 60 * 60 * 24);

      return daysSinceAuth < 30;
    } catch (error) {
      console.error("Error checking session validity: [details redacted]");
      return false;
    }
  }
};

import { supabase, createAuthenticatedSupabaseClient } from './supabase';
import { Community, CommunityMember, CommunityMessage, CommunityType, MemberRole, CommunityFileAttachment } from '../types';
import { RealtimeChannel } from '@supabase/supabase-js';

/**
 * Service for handling community-related operations
 */
export const communityService = {
  /**
   * Create a new community
   */
  async createCommunity(name: string, type: CommunityType, currentUserId?: string, getToken?: () => Promise<string | null>): Promise<Community | null> {
    try {
      if (!currentUserId) {
        console.error("User ID is required to create a community [details redacted]");
        return null;
      }

      console.log("Creating community with user ID: [details redacted]");

      // For now, use the regular supabase client since RLS is disabled
      // We'll add authentication back once the basic functionality works
      const { data, error } = await supabase
        .from('communities')
        .insert({
          name,
          type,
          owner_id: currentUserId,
          invite_code: type === 'private' ? Math.random().toString(36).substr(2, 8).toUpperCase() : null
        })
        .select()
        .single();

      if (error) {
        console.error("Database community creation failed: [details redacted]");
        return null;
      }

      console.log("Community created successfully: [details redacted]");
      return data as Community;
    } catch (error) {
      console.error("Error creating community: [details redacted]");
      return null;
    }
  },

  /**
   * Get all public communities
   */
  async getPublicCommunities(): Promise<Community[]> {
    try {
      const { data, error } = await supabase
        .from('communities')
        .select('*')
        .eq('type', 'public')
        .order('created_at', { ascending: false });

      if (error) throw error;
      return data as Community[];
    } catch (error) {
      console.error("Error fetching public communities: [details redacted]");
      return [];
    }
  },

  /**
   * Get all communities the current user is a member of
   */
  async getUserCommunities(currentUserId?: string): Promise<Community[]> {
    try {
      if (!currentUserId) {
        console.error("User ID is required to get user communities [details redacted]");
        return [];
      }

      const { data, error } = await supabase
        .from('community_members')
        .select('community_id')
        .eq('user_id', currentUserId);

      if (error) throw error;

      if (data.length === 0) return [];

      const communityIds = data.map(item => item.community_id);

      const { data: communities, error: communitiesError } = await supabase
        .from('communities')
        .select('*')
        .in('id', communityIds)
        .order('created_at', { ascending: false });

      if (communitiesError) throw communitiesError;
      return communities as Community[];
    } catch (error) {
      console.error("Error fetching user communities: [details redacted]");
      return [];
    }
  },

  /**
   * Get community previews with member count and last message info for the current user
   */
  async getUserCommunityPreviews(currentUserId?: string): Promise<any[]> {
    try {
      if (!currentUserId) {
        console.error("User ID is required to get user community previews [details redacted]");
        return [];
      }

      // First get all communities the user is a member of
      const { data: memberships, error: membershipError } = await supabase
        .from('community_members')
        .select('community_id')
        .eq('user_id', currentUserId);

      if (membershipError) throw membershipError;

      if (memberships.length === 0) return [];

      const communityIds = memberships.map(item => item.community_id);

      // Get basic community info
      const { data: communities, error: communitiesError } = await supabase
        .from('communities')
        .select('*')
        .in('id', communityIds)
        .order('created_at', { ascending: false });

      if (communitiesError) throw communitiesError;
      if (!communities || communities.length === 0) return [];

      // Get member counts for each community
      const memberCountPromises = communities.map(async (community) => {
        const { count, error } = await supabase
          .from('community_members')
          .select('id', { count: 'exact', head: true })
          .eq('community_id', community.id);

        if (error) throw error;
        return { communityId: community.id, count: count || 0 };
      });

      // Get last message for each community with direct query instead of using a join
      const lastMessagePromises = communities.map(async (community) => {
        // Get the latest message for this community
        const { data, error } = await supabase
          .from('community_messages')
          .select('id, content, created_at, user_id')
          .eq('community_id', community.id)
          .order('created_at', { ascending: false })
          .limit(1);

        if (error) {
          console.error("Error fetching last message: [details redacted]");
          return { communityId: community.id, lastMessage: null };
        }

        // If no messages, return null for lastMessage
        if (!data || data.length === 0) {
          return { communityId: community.id, lastMessage: null };
        }

        // For each message, get the username separately
        const message = data[0];

        try {
          // Get the username for the user who sent the message
          const { data: userData, error: userError } = await supabase
            .from('users')
            .select('username')
            .eq('id', message.user_id)
            .single();

          if (userError) throw userError;

          return { 
            communityId: community.id, 
            lastMessage: {
              content: message.content,
              created_at: message.created_at,
              username: userData?.username
            }
          };
        } catch (e) {
          console.error("Error fetching message sender: [details redacted]");
          return { 
            communityId: community.id, 
            lastMessage: {
              content: message.content,
              created_at: message.created_at,
              username: 'Unknown'
            }
          };
        }
      });

      const memberCounts = await Promise.all(memberCountPromises);
      const lastMessages = await Promise.all(lastMessagePromises);

      // Combine all data
      return communities.map(community => {
        const memberCount = memberCounts.find(item => item.communityId === community.id)?.count || 0;
        const lastMessage = lastMessages.find(item => item.communityId === community.id)?.lastMessage;

        return {
          ...community,
          memberCount,
          lastMessage: lastMessage ? lastMessage.content : null,
          lastMessageUser: lastMessage ? lastMessage.username : null,
          lastMessageTime: lastMessage ? lastMessage.created_at : null
        };
      });
    } catch (error) {
      console.error("Error fetching user community previews: [details redacted]");
      return [];
    }
  },

