    // 1. Update the user's banned status
    const { data, error } = await supabase
      .from('users')
      .update({
        banned: true,
        banned_at: new Date().toISOString(),
        banned_reason: banReason
      })
      .eq('id', userId)
      .select();

    if (error) {
      throw error;
    }

    console.log('User banned successfully:', data);

    // 2. Create a system message (optional)
